import{af as a,z as t,J as s,ab as r}from"./chunks/framework.DOJTDj7A.js";const h=JSON.parse('{"title":"Manage Users","description":"","frontmatter":{"outline":"shallow","order":4},"headers":[],"relativePath":"apps/admin/devices/users.md","filePath":"apps/admin/devices/users.md"}'),o={name:"apps/admin/devices/users.md"};function i(n,e,c,d,l,u){return t(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792763086000"},[...e[0]||(e[0]=[r('<h1 id="manage-users" tabindex="-1">Manage Users <a class="header-anchor" href="#manage-users" aria-label="Permalink to &quot;Manage Users&quot;">​</a></h1><p>Clicking on the manage users icon will open a dialog allowing you to add or remove users from the device.</p><p>Users can have different global permissions, which can be controlled from the <a href="/docs/branch/31d42f615ccbbe66611e36a9fbfe42b065e51be507b5dab276c3de717a9a0d26/apps/admin/users#permissions">users page</a>.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/yIbkNpT.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="add-existing-user" tabindex="-1">Add Existing user <a class="header-anchor" href="#add-existing-user" aria-label="Permalink to &quot;Add Existing user&quot;">​</a></h2><p>In order to select an existing user, click on their name from the list.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/5aFeQlp.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>On success, you&#39;ll see a confirmation message in the top right corner.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Warning</p><p>If the user already exists, and they are not a sub user of your account, you will not be able to select them. If this is the case please contact support to get them added to your account.</p></div><h2 id="add-new-user" tabindex="-1">Add New user <a class="header-anchor" href="#add-new-user" aria-label="Permalink to &quot;Add New user&quot;">​</a></h2><p>To create a new user, click on the <code>Create New</code> button.</p><p>This will open a dialog allowing you to enter the new users details.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/QEnoQwF.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>Once you have entered the details, click <code>Create</code> to create the user.</p><p>On success, you&#39;ll see a confirmation message in the top right corner.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Warning</p><p>If the user already exists, you will not be able to create an account for them.</p></div><h2 id="remove-a-user" tabindex="-1">Remove a user <a class="header-anchor" href="#remove-a-user" aria-label="Permalink to &quot;Remove a user&quot;">​</a></h2><p>To remove a user from the device, click on the <code>X</code> icon next to their name.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/HBqlqN1.png" alt="" tabindex="0"><figcaption></figcaption></figure>',19)])])}const g=a(o,[["render",i]]);export{h as __pageData,g as default};
